model_name = "deepseek-ai/DeepSeek-R1-Distill-Qwen-7B"
tokenizer = AutoTokenizer.from_pretrained(model_name)

tokenizer.pad_token = tokenizer.eos_token
tokenizer.pad_token_id = tokenizer.eos_token_id
# tokenizer.padding_side = "left"

model = AutoModelForCausalLM.from_pretrained(
    model_name,
    torch_dtype="auto",
    device_map="auto"
)

def build_prompt(user_content):
    """
    We add a system role instructing the model to be DeepSeek-R1,
    then place the user content, finishing with 'Assistant:' as a signal.
    """
    system_message = (
                            "You are a helpful assistant.Your answers should be plain text "
                            "without using special characters, bullet points, or lists. "
                            "Don't repeat the question in your answer and just provide the answer "
                            "at most 125 tokens."
                        )
    return (
        f"System: {system_message}\n"
        f"User: {user_content}\n"
        "Assistant:"
    )

def generate_outputs(prompt, views, num_samples, batch_size, max_length, temperature=0.9):
    outputs = []
    num_batches = (num_samples + batch_size - 1) // batch_size 

    for batch_idx in range(num_batches):

        selected_views = random.choices(views, k=min(batch_size, num_samples - len(outputs)))

        batch_prompts = [
            (
                f"{prompt}\n"
                "Your answers should be plain text and use details in this image description in your answer:\n"
                f"{view}"
            )
            for view in selected_views
        ]

        
        prompt_texts = [build_prompt(p) for p in batch_prompts]

       
        model_inputs = tokenizer(
            prompt_texts,
            return_tensors="pt",
            padding=True,
            truncation=True,
            add_special_tokens=True
        ).to(model.device)

        
        generated_ids = model.generate(
            **model_inputs,
            max_new_tokens=max_length,
            do_sample=True,
            temperature=temperature,
            top_p=0.95
        )

       
        for input_ids, output_ids, view_str, combined_prompt in zip(
            model_inputs.input_ids, generated_ids, selected_views, batch_prompts
        ):
    
            generated_ids_trimmed = output_ids[len(input_ids):]
            response = tokenizer.decode(generated_ids_trimmed, skip_special_tokens=True)

            # --------------- LOGGING ---------------
            #print("=" * 70)
            #print(f"Batch Index: {batch_idx + 1}")
            #print(f"Selected Random View:\n{view_str}")
            #print("\nFull User Prompt (system + user) Sent to Model:\n")
            #print(build_prompt(combined_prompt))
            #print("\nModel Response:\n")
            #print(response)
            #print("=" * 70)

            outputs.append(response)

    return outputs


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generate text outputs from prompts.")
    parser.add_argument("--num_samples", type=int, required=True,
                        help="Number of samples to generate per prompt.")
    parser.add_argument("--max_length", type=int, required=True,
                        help="Maximum length of generated text.")
    args = parser.parse_args()

    num_samples = args.num_samples
    max_length = args.max_length
    batch_size = 100  

    print(f"Generating {num_samples} samples with max length {max_length}...")


    all_outputs = {}
    for prompt in prompts:
        outputs = generate_outputs(
            prompt,
            views=image_views[prompt],
            num_samples=num_samples,
            batch_size=batch_size,
            max_length=max_length
        )
        all_outputs[prompt] = outputs

   
    output_file = f"deepseek_imv_{num_samples}{max_length}.json"
    with open(output_file, "w") as f:
        json.dump(all_outputs, f, indent=4)

    print(f"Outputs saved to {output_file}")

